<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
use EpaperSaas\Core\{RequestContext,Store,Uuid};
use EpaperSaas\Services\{QueueService,RabbitMq};
$r=RabbitMq::instance();$ping=$r->ping();$deliveries=[];foreach(['render','assets','ocr','finalize'] as$lane){$v=Store::value('SELECT state_value FROM ep_system_state WHERE state_key=?',['queue.delivery.'.$lane]);$deliveries[$lane]=$v?json_decode((string)$v,true):null;}
$original=RequestContext::all();$tenantTransport=[];$totals=['db_queued'=>0,'db_retry_wait'=>0,'dispatch_pending'=>0,'dispatch_processing'=>0,'dispatch_confirmed'=>0,'dispatch_failed'=>0,'missing_dispatch_receipt'=>0,'failed_total'=>0,'failed_actionable'=>0,'failed_closeable'=>0];
foreach(Store::all('SELECT tenant_guid,display_name,organisation_guid FROM ep_tenants ORDER BY display_name') as$t){$tg=Uuid::fromBinary($t['tenant_guid']);RequestContext::set(['tenant_guid'=>$tg,'tenant_name'=>$t['display_name']??'Publisher','organisation_guid'=>!empty($t['organisation_guid'])?Uuid::fromBinary($t['organisation_guid']):null,'request_guid'=>Uuid::v7(),'correlation_guid'=>Uuid::v7()]);$d=QueueService::dispatchAnalysis($tg);$o=QueueService::outboxBacklog($tg);$row=['tenant_guid'=>$tg,'tenant_name'=>$t['display_name']??'Publisher','db_queued'=>$d['db_queued'],'db_retry_wait'=>$d['db_retry_wait'],'dispatch_pending'=>$d['dispatch_pending'],'dispatch_processing'=>$d['dispatch_processing'],'dispatch_confirmed'=>$d['dispatch_confirmed'],'dispatch_failed'=>$d['dispatch_failed'],'missing_dispatch_receipt'=>$d['missing_dispatch_receipt'],'failed_total'=>$o['failed_total'],'failed_actionable'=>$o['failed_actionable'],'failed_closeable'=>$o['failed_closeable']];$tenantTransport[]=$row;foreach($totals as$k=>$v)$totals[$k]+=(int)($row[$k]??0);}
if($original)RequestContext::set($original);
$out=['ok'=>(bool)$ping['ok'],'driver'=>QueueService::driver(),'dependency_available'=>$r->dependencyAvailable(),'rabbitmq'=>$ping,'queues'=>$r->queueStats(),'transport_summary'=>$totals,'tenant_transport'=>$tenantTransport,'db_jobs'=>['queued'=>(int)Store::value('SELECT COUNT(*) FROM ep_processing_jobs WHERE status="QUEUED"'),'running'=>(int)Store::value('SELECT COUNT(*) FROM ep_processing_jobs WHERE status="RUNNING"'),'retry_wait'=>(int)Store::value('SELECT COUNT(*) FROM ep_processing_jobs WHERE status="RETRY_WAIT"'),'failed'=>(int)Store::value('SELECT COUNT(*) FROM ep_processing_jobs WHERE status="FAILED"')],'last_business_delivery'=>$deliveries,'version'=>trim((string)@file_get_contents(dirname(__DIR__).'/VERSION'))];
echo json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)."\n";exit($out['ok']?0:1);
